/// One named equalizer preset. Hardware-verified on the 670NC, 2026-10-22: each case's
/// `transaction` was captured via PacketLogger from an isolated single-tap session in the real
/// JBL app (one preset per capture, never inferred from a multi-tap batch — an early attempt
/// at inferring preset identity from tap order produced a real, confirmed-wrong mapping), then
/// replayed over the classic RFCOMM bridge and confirmed by ear against each preset's own
/// character. `.off` is not a case here — turning the Equalizer off sends the exact same
/// transaction as `.studio` (byte-for-byte confirmed identical capture-to-capture); there is no
/// separate device-level "off" state, only the UI concept of one. Turning it back on replays
/// whichever preset was last selected.
enum EqualizerPreset: String, CaseIterable, Identifiable {
    case studio, bass, club, extremeBass, vocal, jazz
    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .studio: return "Studio"
        case .bass: return "Bass"
        case .club: return "Club"
        case .extremeBass: return "Extreme Bass"
        case .vocal: return "Vocal"
        case .jazz: return "Jazz"
        }
    }

